/// <summary>
/// Extension of SalesTable form datafield.
/// </summary>
[ExtensionOf(formDataFieldStr(SalesTable, InventDim, InventLocationId))]
final class METSalesTableFormInventDimDSInventLocationId_Extension
{
}

Method.Source:
    /// <summary>
    /// Modified the dimensionvalue.
    /// </summary>
    public void modified()
    {
        InventDim       inventDim;
        FormDataSource  fds;
        FormDataObject  fdo = any2Object(this) as FormDataObject;

        next modified();

        fds         = fdo.datasource();
        inventDim   = fds.cursor();
        
        FormDataSource  salesLine_ds = fds.formRun().dataSource(formDataSourceStr(SalesTable, SalesLine));
        SalesLine       salesLine = salesLine_ds.cursor();

        if (inventDim.InventLocationId)
        {
            salesLine.DefaultDimension = InventLocation::changeDimension(salesLine.DefaultDimension, inventDim.InventLocationId);
        }

        DimensionDisplayValue dimensionValue = METInventJournalEventHandler::getDimensionDisplayValue(salesLine.DefaultDimension, "@MET:ProfitCenter");
        if(!dimensionValue || !inventDim.InventLocationId)
        {
            salesLine.DefaultDimension = InventSite::changeDimension(salesLine.DefaultDimension, InventSite::find(inventDim.InventSiteId).SiteId);
        }
    }
